package com.mochikibun.monsthub;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.time.*;
public class PlannerTest {
 private String account(HubState s,int n)throws Exception{return s.accounts().getJSONObject(n).getString("id");}
 private JSONObject deadlines(JSONObject r)throws Exception{return r.put("due","2026-10-20T12:00:00+09:00").put("notify",true).put("lead_hours",24);}
 private JSONObject own(HubState s,String cid,int n)throws Exception{return new JSONObject().put("id",PlannerData.id()).put("account_id",account(s,n)).put("catalog_id",cid).put("name","テストキャラ").put("element","火").put("form","獣神化改").put("count",2).put("luck",5).put("trained",false).put("fruit","同族加撃").put("target_fruit","同族加撃L").put("memo","メモ");}
 @Test public void v02BackupMigratesWithoutLosingRecords()throws Exception{HubState s=HubState.create();s.setOrbs(account(s,0),123,"",Instant.EPOCH);JSONObject old=new JSONObject(s.json());old.put("schema_version",1);old.remove("planner");old.remove("bond_reset_hour");HubState migrated=HubState.parse(old.toString());assertEquals(12,migrated.accounts().length());assertEquals(123,migrated.totalOrbs());assertEquals(4,migrated.root.getInt("bond_reset_hour"));assertEquals(0,migrated.planner().list("inventory").length());}
 @Test public void catalogAndCustomOwnershipSearchAcrossAccounts()throws Exception{HubState s=HubState.create();s.planner().put("inventory",own(s,"gw:123",0));s.planner().put("inventory",own(s,"gw:123",1));s.planner().put("inventory",own(s,"custom:abc",2));assertEquals(4,s.planner().owned("gw:123",""));assertEquals(2,s.planner().owned("gw:123",account(s,1)));assertEquals(2,s.planner().ownedIds("").size());assertEquals(1,s.planner().ownedIds(account(s,2)).size());assertEquals(3,s.copy().planner().list("inventory").length());}
 @Test public void customCharactersSurviveBackupAndHaveSeparateIds()throws Exception{HubState s=HubState.create();s.planner().put("custom_characters",new JSONObject().put("id","custom:abc").put("name","新しい形態").put("element","闇").put("form","真獣神化").put("no",""));s.planner().put("inventory",own(s,"custom:abc",0));HubState restored=s.copy();assertEquals("新しい形態",restored.planner().find("custom_characters","custom:abc").getString("name"));assertEquals(2,restored.planner().owned("custom:abc",""));}
 @Test public void teamCheckUsesCorrectDayAndOnlyTeamMembers()throws Exception{HubState s=HubState.create();s.root.put("bond_reset_hour",0);JSONObject t=new JSONObject().put("id","team").put("name","A").put("members",new JSONArray().put(account(s,0)).put(account(s,1)));s.planner().put("teams",t);Instant now=Instant.parse("2026-10-18T16:00:00Z");s.planner().teamCheck("team","bond",true,now);assertTrue(s.checked(LocalDate.of(2026,10,19),account(s,0),"bond"));assertFalse(s.checked(LocalDate.of(2026,10,19),account(s,2),"bond"));assertEquals(LocalDate.of(2026,10,18),s.day(now));assertEquals(1,s.copy().planner().list("teams").length());}
 @Test(expected=Exception.class)public void moreThanFourTeamMembersRejected()throws Exception{HubState s=HubState.create();JSONArray m=new JSONArray();for(int i=0;i<5;i++)m.put(account(s,i));s.planner().put("teams",new JSONObject().put("id","bad").put("name","bad").put("members",m));s.copy();}
 @Test public void collectedOrbsCannotBeCollectedTwice()throws Exception{HubState s=HubState.create();JSONObject p=deadlines(new JSONObject().put("id","plan").put("name","予定").put("account_id",account(s,0)).put("amount",50).put("received",false));s.planner().put("orb_plans",p);assertEquals(50,s.planner().expectedOrbs(account(s,0)));s.planner().collect("plan",Instant.EPOCH);assertEquals(50,s.totalOrbs());assertEquals(0,s.planner().expectedOrbs(account(s,0)));try{s.planner().collect("plan",Instant.EPOCH);fail();}catch(IllegalArgumentException expected){}assertEquals(50,s.totalOrbs());assertEquals(1,s.copy().history().length());}
 @Test public void deletingAccountCleansNewReferences()throws Exception{HubState s=HubState.create();String id=account(s,0);s.planner().put("inventory",own(s,"gw:1",0));s.planner().put("teams",new JSONObject().put("id","t").put("name","t").put("members",new JSONArray().put(id)));s.planner().put("missions",deadlines(new JSONObject().put("id","m").put("name","月間").put("period","2026-10").put("memo","").put("progress",new JSONObject().put(id,3))));s.deleteAccount(id);assertEquals(0,s.planner().list("inventory").length());assertEquals(0,s.planner().list("teams").length());assertEquals(0,s.copy().planner().find("missions","m").getJSONObject("progress").length());}
 @Test public void extendedBackupPreservesEveryTable()throws Exception{HubState s=HubState.create();String id=account(s,0);s.planner().put("missions",deadlines(new JSONObject().put("id","m").put("name","月間").put("period","2026-10").put("memo","memo").put("progress",new JSONObject().put(id,2))));s.planner().put("goals",deadlines(new JSONObject().put("id","g").put("account_id",id).put("name","運極").put("current",45).put("target",99).put("memo","team")));s.planner().put("formations",new JSONObject().put("id","f").put("name","攻略").put("members",new JSONArray().put(new JSONObject().put("account_id",id).put("character","キャラ"))).put("memo","実と紋章").put("image",java.util.Base64.getEncoder().encodeToString(new byte[]{1,2,3})));s.planner().setOrbTarget(id,100);HubState r=s.copy();assertEquals(2,r.planner().find("missions","m").getJSONObject("progress").getInt(id));assertEquals(45,r.planner().find("goals","g").getInt("current"));assertEquals("実と紋章",r.planner().find("formations","f").getString("memo"));assertEquals(100,r.planner().orbTarget(id));}
 @Test(expected=Exception.class)public void invalidPlannerReferenceRejected()throws Exception{HubState s=HubState.create();JSONObject r=own(s,"gw:1",0);r.put("account_id","missing");s.planner().put("inventory",r);s.copy();}
 @Test public void nameNormalizationMatchesKanaAndWidth(){assertEquals(CatalogRepository.normalize("ルシファー"),CatalogRepository.normalize("るしふぁー"));assertEquals(CatalogRepository.normalize("ﾈｵ"),CatalogRepository.normalize("ネオ"));assertEquals("abc",CatalogRepository.normalize("ＡＢＣ"));}

 @Test public void automaticCatalogUpdateFreshness(){Instant now=Instant.parse("2026-10-18T12:00:00Z");assertFalse(CatalogUpdates.stale("2026-10-18T11:00:00Z",now));assertTrue(CatalogUpdates.stale("2026-10-17T12:00:00Z",now));assertTrue(CatalogUpdates.stale("未取得",now));}
}
